  const rebookable = pets.flatMap((pet) => (pet.appointments ?? []).filter((appointment) => ['COMPLETED', 'READY'].includes(appointment.state) && appointment.variantId && appointment.locationId).map((appointment) => ({ pet, appointment }))).slice(-8).reverse();
  const petName = new Map(pets.map((pet) => [pet.id, pet.name]));
  const liveVisits = pets.flatMap((pet) => (pet.intelligence?.activeVisits ?? []).map((visit) => ({ pet, visit })));
  const inboxThreads = inbox.threads ?? [];
  const clientInbox = `<article class="timeline client-inbox" style="grid-column:1/-1"><header><div><p class="eyebrow">ЕДИНЫЙ ДИАЛОГ</p><h2>Можно просто написать.</h2><p>Сайт и Telegram продолжают один разговор. Команда видит контекст питомца, а вы — весь путь до результата.</p></div><b>${inboxThreads.filter((item) => item.state !== 'RESOLVED').length}</b></header><div class="client-inbox-grid"><form id="client-inbox-new"><select name="petId"><option value="">Общий вопрос</option>${pets.map((pet) => `<option value="${experienceEscape(pet.id)}">О ${experienceEscape(pet.name)}</option>`).join('')}</select><textarea name="message" minlength="3" maxlength="5000" required placeholder="Напишите своими словами. Если питомцу плохо прямо сейчас — не ждите ответа в чате."></textarea><button class="button">Передать команде →</button><span data-inbox-status></span></form><div class="client-thread-list">${inboxThreads.map((thread) => `<details ${thread.state !== 'RESOLVED' ? 'open' : ''}><summary><span><b>${experienceEscape(thread.subject)}</b><small>${experienceEscape(thread.state)} · ${new Date(thread.updatedAt).toLocaleString('ru-RU', { dateStyle: 'short', timeStyle: 'short' })}</small></span><em>${thread.messages.length}</em></summary><div>${thread.messages.map((message) => `<article class="${message.authorType === 'STAFF' ? 'staff' : 'owner'}"><small>${message.authorType === 'STAFF' ? 'Команда VetSvet' : 'Вы'}</small><p>${experienceEscape(message.body)}</p></article>`).join('')}</div>${thread.state !== 'RESOLVED' ? `<form data-client-thread="${experienceEscape(thread.id)}"><input name="message" required placeholder="Продолжить диалог"><button>Отправить</button></form>` : `<p class="client-thread-outcome"><b>Результат:</b> ${experienceEscape(thread.outcome || 'Диалог завершён')}</p>`}</details>`).join('') || '<p class="client-inbox-empty">Диалог начнётся с вашего первого сообщения.</p>'}</div></div></article>`;
  const trustedSteps = pets.flatMap((pet) => (pet.intelligence?.recommendations ?? []).filter((item) => item.state !== 'COMPLETED').map((item) => ({ pet, item }))).slice(0, 12);
  const memoryNodes = pets.flatMap((pet) => (pet.intelligence?.memoryGraph?.nodes ?? []).map((node) => ({ pet, node }))).sort((left, right) => new Date(right.node.occurredAt) - new Date(left.node.occurredAt)).slice(0, 12);
