    const sheet = document.createElement('div'); sheet.className = 'rebook-sheet'; sheet.innerHTML = `<div class="rebook-scrim" data-close></div><article><button type="button" class="rebook-close" data-close>×</button><p class="eyebrow">ПЕРЕНОС БЕЗ ЗВОНКА</p><h2>Найдём новое спокойное окно.</h2><p>Старая запись останется на месте, пока вы не подтвердите новое время.</p><label>Новый день<input type="date" value="${experienceEscape(defaultDate)}" min="${experienceEscape(defaultDate)}"></label><div class="rebook-slots"><span>Ищем свободные окна…</span></div><div class="rebook-status"></div></article>`; document.body.append(sheet); requestAnimationFrame(() => sheet.classList.add('open'));
